#!/usr/bin/env python3
"""Token Alert Terminal Checker - Reads session data and displays usage status."""

import json
from pathlib import Path

def load_session_data():
    """Load session data from the deterministic sample file."""
    data_path = Path(__file__).parent.parent / 'input' / 'session_data.json'
    with open(data_path, 'r', encoding='utf-8') as f:
        return json.load(f)

def calculate_percentage(used, limit):
    """Calculate usage percentage."""
    return (used / limit) * 100

def get_warning_level(percentage, thresholds):
    """Determine warning level based on percentage and thresholds."""
    thresholds = sorted(thresholds)

    if percentage >= 100:
        return '🚨', 'Emergency', '100% - Token limit reached!'
    for threshold in reversed(thresholds):
        if percentage >= threshold:
            if threshold >= 95:
                return '🚨', 'Emergency', f'{threshold}% zone - Critical!'
            elif threshold >= 90:
                return '🔴', 'Critical Warning', f'{threshold}% zone - Critical!'
            elif threshold >= 75:
                return '🔶', 'High Warning', f'{threshold}% zone - High Warning'
            elif threshold >= 50:
                return '🟠', 'Medium Warning', f'{threshold}% zone - Medium Warning'
            else:
                return '🟡', 'Low Warning', f'{threshold}% zone - Low Warning'
    return '✅', 'OK', 'Below all thresholds'

def create_progress_bar(percentage, width=30):
    """Create a box-style progress bar (▰/▱)."""
    filled = int(percentage / 100 * width)
    filled = min(filled, width)
    bar = '▰' * filled + '▱' * (width - filled)
    return bar

def estimate_remaining_sessions(remaining, avg_per_session=50000):
    """Estimate remaining sessions based on average token usage."""
    if remaining <= 0:
        return '<1 Session'
    sessions = remaining / avg_per_session
    if sessions < 1:
        return '<1 Session'
    return f'~{int(sessions)} Sessions'

def main():
    # Load data
    data = load_session_data()

    limit = data['limit']
    used = data['used']
    thresholds = data.get('thresholds', [25, 50, 75, 90, 95])

    percentage = calculate_percentage(used, limit)
    remaining = limit - used
    icon, status, status_detail = get_warning_level(percentage, thresholds)
    progress_bar = create_progress_bar(percentage)
    sessions_left = estimate_remaining_sessions(remaining)

    # Display output
    print(f"\n{icon} Token Alert: {status}")
    print()
    print(f"{icon} {progress_bar} {percentage:.1f}%")
    print(f"{used:,} / {limit:,} Tokens verwendet")
    print()
    print(f"⚠️ Status: {status_detail}")
    print(f"💡 Verbleibend: ~{remaining:,} Tokens")
    print(f"⏰ Geschätzte Sessions: {sessions_left}")
    print()

    # Recommendations based on level
    if percentage >= 75:
        print("🔧 Empfehlung:")
        print("   ✅ Wichtige Entscheidungen jetzt treffen")
        print("   ✅ Neue Session vorbereiten")
        print("   ✅ Token-Limit prüfen und ggf. erhöhen")
